  "CREATE TRIGGER attachment_owner_reject_deleting BEFORE INSERT ON attachment_owners\n    WHEN EXISTS (SELECT 1 FROM attachments WHERE attachment_id = NEW.attachment_id AND lifecycle = 'deleting')\n    BEGIN SELECT RAISE(ABORT, 'Attachment is unavailable: deletion in progress'); END",
  "CREATE TRIGGER attachment_reject_replacement BEFORE INSERT ON attachments\n    WHEN EXISTS (SELECT 1 FROM attachments WHERE attachment_id = NEW.attachment_id AND lifecycle = 'deleting')\n    BEGIN SELECT RAISE(ABORT, 'Attachment is unavailable: deletion in progress'); END",
  "CREATE TRIGGER attachment_reject_resurrection BEFORE UPDATE OF lifecycle ON attachments\n    WHEN OLD.lifecycle = 'deleting' AND NEW.lifecycle <> 'deleting'\n    BEGIN SELECT RAISE(ABORT, 'Attachment is unavailable: deletion in progress'); END",
  "CREATE TRIGGER search_documents_after_delete\n    AFTER DELETE ON search_documents BEGIN\n      INSERT INTO search_documents_fts(search_documents_fts, rowid, title, content, path)\n      VALUES ('delete', old.rowid, old.title, old.content, old.path);\n    END",
  "CREATE TRIGGER search_documents_after_insert\n    AFTER INSERT ON search_documents BEGIN\n      INSERT INTO search_documents_fts(rowid, title, content, path)\n      VALUES (new.rowid, new.title, new.content, new.path);\n    END",
  "CREATE TRIGGER search_documents_after_update\n    AFTER UPDATE ON search_documents BEGIN\n      INSERT INTO search_documents_fts(search_documents_fts, rowid, title, content, path)\n      VALUES ('delete', old.rowid, old.title, old.content, old.path);\n      INSERT INTO search_documents_fts(rowid, title, content, path)\n      VALUES (new.rowid, new.title, new.content, new.path);\n    END",
  "CREATE TRIGGER search_projection_code_review_workflows_delete\n      AFTER DELETE ON projection_code_review_workflows BEGIN\n        DELETE FROM search_documents WHERE document_key = 'workflow.codeReview:' || old.workflow_id;\n      END",
  "CREATE TRIGGER search_projection_code_review_workflows_insert\n      AFTER INSERT ON projection_code_review_workflows BEGIN \n      DELETE FROM search_documents\n      WHERE document_key = 'workflow.codeReview:' || new.workflow_id;\n      INSERT INTO search_documents (\n        document_key, kind, entity_id, project_id, workflow_id, title, content, created_at\n      )\n      SELECT\n        'workflow.codeReview:' || new.workflow_id,\n        'workflow.codeReview', new.workflow_id, new.project_id, new.workflow_id,\n        coalesce(json_extract(new.workflow_json, '$.title'), 'Workflow'),\n        coalesce(json_extract(new.workflow_json, '$.reviewPrompt'), ''),\n        coalesce(json_extract(new.workflow_json, '$.createdAt'), new.updated_at)\n      WHERE new.deleted_at IS NULL\n        AND json_extract(new.workflow_json, '$.deletedAt') IS NULL;\n     END",
