  "CREATE TRIGGER search_projection_thread_activities_delete\n      AFTER DELETE ON projection_thread_activities BEGIN\n        DELETE FROM search_documents WHERE document_key = 'activity:' || old.activity_id;\n      END",
  "CREATE TRIGGER search_projection_thread_activities_insert\n      AFTER INSERT ON projection_thread_activities BEGIN \n    DELETE FROM search_documents WHERE document_key = 'activity:' || new.activity_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, turn_id,\n      title, content, created_at\n    )\n    SELECT\n      'activity:' || new.activity_id, 'activity', new.activity_id, thread.project_id,\n      new.thread_id, new.turn_id, new.summary, new.summary, new.created_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id\n      AND thread.deleted_at IS NULL\n      AND length(trim(new.summary)) > 0;\n   END",
  "CREATE TRIGGER search_projection_thread_activities_update\n      AFTER UPDATE ON projection_thread_activities BEGIN \n    DELETE FROM search_documents WHERE document_key = 'activity:' || new.activity_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, turn_id,\n      title, content, created_at\n    )\n    SELECT\n      'activity:' || new.activity_id, 'activity', new.activity_id, thread.project_id,\n      new.thread_id, new.turn_id, new.summary, new.summary, new.created_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id\n      AND thread.deleted_at IS NULL\n      AND length(trim(new.summary)) > 0;\n   END",
  "CREATE TRIGGER search_projection_thread_file_changes_delete\n      AFTER DELETE ON projection_thread_file_changes BEGIN\n        DELETE FROM search_documents WHERE document_key = 'file-change:' || old.file_change_id;\n      END",
  "CREATE TRIGGER search_projection_thread_file_changes_insert\n      AFTER INSERT ON projection_thread_file_changes BEGIN \n    DELETE FROM search_documents WHERE document_key = 'file-change:' || new.file_change_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, turn_id, file_change_id,\n      title, content, path, created_at\n    )\n    SELECT\n      'file-change:' || new.file_change_id, 'fileChange', new.file_change_id,\n      thread.project_id, new.thread_id, new.turn_id, new.file_change_id,\n      coalesce(new.title, 'Changed files'), coalesce(new.detail, ''), new.changed_files,\n      new.started_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id AND thread.deleted_at IS NULL;\n   END",
  "CREATE TRIGGER search_projection_thread_file_changes_update\n      AFTER UPDATE ON projection_thread_file_changes BEGIN \n    DELETE FROM search_documents WHERE document_key = 'file-change:' || new.file_change_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, turn_id, file_change_id,\n      title, content, path, created_at\n    )\n    SELECT\n      'file-change:' || new.file_change_id, 'fileChange', new.file_change_id,\n      thread.project_id, new.thread_id, new.turn_id, new.file_change_id,\n      coalesce(new.title, 'Changed files'), coalesce(new.detail, ''), new.changed_files,\n      new.started_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id AND thread.deleted_at IS NULL;\n   END",
  "CREATE TRIGGER search_projection_thread_messages_delete\n      AFTER DELETE ON projection_thread_messages BEGIN\n        DELETE FROM search_documents WHERE document_key = 'message:' || old.message_id;\n      END",
  "CREATE TRIGGER search_projection_thread_messages_insert AFTER INSERT ON projection_thread_messages BEGIN \n    DELETE FROM search_documents WHERE document_key = 'message:' || new.message_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, message_id, turn_id,\n      title, content, role, created_at\n    )\n    SELECT\n      'message:' || new.message_id, 'message', new.message_id, thread.project_id,\n      new.thread_id, new.message_id, new.turn_id, thread.title, new.text, new.role, new.created_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id\n      AND thread.deleted_at IS NULL\n      AND new.role IN ('user', 'assistant')\n      AND length(trim(new.text)) > 0\n      AND (new.role <> 'user' OR trim(new.text, char(32, 9, 10, 11, 12, 13)) <> '[User attached one or more images without additional text. Respond using the conversation context and the attached image(s).]');\n   END",
  "CREATE TRIGGER search_projection_thread_messages_update AFTER UPDATE ON projection_thread_messages BEGIN \n    DELETE FROM search_documents WHERE document_key = 'message:' || new.message_id;\n    INSERT INTO search_documents (\n      document_key, kind, entity_id, project_id, thread_id, message_id, turn_id,\n      title, content, role, created_at\n    )\n    SELECT\n      'message:' || new.message_id, 'message', new.message_id, thread.project_id,\n      new.thread_id, new.message_id, new.turn_id, thread.title, new.text, new.role, new.created_at\n    FROM projection_threads AS thread\n    WHERE thread.thread_id = new.thread_id\n      AND thread.deleted_at IS NULL\n      AND new.role IN ('user', 'assistant')\n      AND length(trim(new.text)) > 0\n      AND (new.role <> 'user' OR trim(new.text, char(32, 9, 10, 11, 12, 13)) <> '[User attached one or more images without additional text. Respond using the conversation context and the attached image(s).]');\n   END",
